<script setup lang="ts">
import {useLocalPagination} from './localPagination'
import {can,firstAllowed} from './session'
import MailAuthorization from './MailAuthorization.vue'
import MailPanel from './MailPanel.vue'
import CompliancePanel from './CompliancePanel.vue'
import DataSyncPanel from './DataSyncPanel.vue'
import AdsQueuePanel from './AdsQueuePanel.vue'
import {useTableWidths} from './tableWidths'
const widths=useTableWidths('SettingsPanel')
import {ref,reactive,onMounted,watch,computed} from 'vue'
import {api,session} from './session'
import {ElMessage,ElMessageBox} from 'element-plus'
const tab=ref(firstAllowed('settings',['warehouses', 'stores', 'addresses', 'profiles', 'sync-data',...(session.value?.is_admin?['ads-queue']:[]),'mail'])),rows=ref<any[]>([]),stores=ref<string[]>([]),store=ref(''),error=ref(''),busy=ref(false),dialog=ref(false),editing=ref<any>(),form=reactive<any>({})
const addressFields:Record<string,string>={name:'联系人',companyName:'公司名称',addressLine1:'街道地址',addressLine2:'地址补充',city:'城市',stateOrProvinceCode:'省 / 州',countryCode:'国家代码',postalCode:'邮编',phoneNumber:'电话',email:'邮箱'}
const profileFields:Record<string,string>={representative_name:'英代 / 欧代联系人',representative_company:'英代 / 欧代公司',representative_email:'英代 / 欧代邮箱',representative_address:'英代 / 欧代地址',manufacturer_company:'制造商名称',manufacturer_email:'制造商邮箱',manufacturer_address:'制造商地址'}
const searchText=ref(''),appliedSearch=ref('')
const filteredRows=computed(()=>rows.value.filter(r=>String(r.name||'').toLowerCase().includes(appliedSearch.value.trim().toLowerCase())))
async function load(){if(['clearance','declaration','sync-data','ads-queue','profiles','mail'].includes(tab.value))return;busy.value=true;error.value='';try{stores.value=(await api('/options')).stores;rows.value=tab.value==='warehouses'?(await api('/warehouse/options')).warehouses:tab.value==='stores'?await api('/settings/stores'):tab.value==='addresses'?(await Promise.all((store.value?[store.value]:stores.value).map(s=>api('/sta/addresses?address_type=all&store='+encodeURIComponent(s))))).flat():(await api('/shipping/profiles')).rows}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch(tab,()=>{searchText.value='';appliedSearch.value='';load()});onMounted(load)
function edit(row?:any){editing.value=row;Object.keys(form).forEach(k=>delete form[k]);if(tab.value==='warehouses')Object.assign(form,{name:row?.name||'',manager:row?.manager||'',address:row?.address||''});else if(tab.value==='stores')Object.assign(form,{name:row?.name||'',seller_id:row?.seller_id||'',client_id:row?.client_id||'',client_secret:'',refresh_token:'',proxy_protocol:row?.proxy_protocol||'http',proxy_host:row?.proxy_host||'',proxy_port:row?.proxy_port||null,proxy_username:row?.proxy_username||'',proxy_password:'',upstream_proxy:row?.upstream_proxy||'',ads_client_id:row?.ads_client_id||'',ads_client_secret:'',ads_refresh_token:'',ads_api_url:row?.ads_api_url||'https://advertising-api-eu.amazon.com',clear_secrets:[]});else if(tab.value==='addresses'){Object.assign(form,{id:row?.id,address_type:row?.address_type||'fba',store:row?.store||store.value||session.value?.current_store||stores.value[0]||'',country:row?.country||'UK',label:row?.label||'',detail:{countryCode:'CN',...row?.detail}});for(const k in addressFields)form.detail[k]??=''}else{Object.assign(form,{store:row?.store||store.value,country:row?.country||'UK',revision:row?.revision||0,representative_expires:null,show_marks:true,...row?.detail});for(const k in profileFields)form[k]??=''}dialog.value=true}
function copyAddress(row:any){edit(JSON.parse(JSON.stringify(row)));editing.value=undefined;delete form.id}
async function discoverAds(name:string){try{const r=await api('/settings/stores/'+encodeURIComponent(name)+'/discover-ads',{});ElMessage.success('已同步 '+r.count+' 个广告账户')}catch(e){ElMessage.error((e as Error).message)}}
const requiredAddressFields=['name','addressLine1','city','countryCode','postalCode','phoneNumber']
const addressLimits:Record<string,number>={name:50,companyName:50,addressLine1:180,addressLine2:60,city:30,stateOrProvinceCode:64,countryCode:2,postalCode:32,phoneNumber:20,email:1024}
function addressPayload(){
 if(!form.store)throw new Error('请选择店铺')
 const detail=Object.fromEntries(Object.keys(addressFields).map(k=>[k,String(form.detail[k]||'').trim()]))
 detail.countryCode=detail.countryCode.toUpperCase()
 for(const k of requiredAddressFields)if(!detail[k])throw new Error('请填写'+addressFields[k])
 for(const [k,max] of Object.entries(addressLimits))if(detail[k].length>max)throw new Error(addressFields[k]+'不能超过 '+max+' 个字符')
 if(!/^[A-Z]{2}$/.test(detail.countryCode))throw new Error('发货国家代码请填写两位英文字母，例如 DE')
 const label=String(form.label||'').trim()||[detail.city,detail.addressLine1].filter(Boolean).join(' · ').slice(0,100)
 if(label.length>100)throw new Error('地址名称不能超过 100 个字符')
 return {...form,country:'',label,detail}
}
async function save(){busy.value=true;try{const path=tab.value==='warehouses'?(editing.value?'/settings/warehouses/'+editing.value.id:'/warehouse/warehouses'):tab.value==='stores'?'/settings/stores/'+encodeURIComponent(form.name):tab.value==='addresses'?'/sta/addresses':'/shipping/profiles';await api(path,tab.value==='stores'?Object.fromEntries(Object.entries(form).filter(([k])=>k!=='name')):tab.value==='addresses'?addressPayload():form);dialog.value=false;await load();ElMessage.success('已保存')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function remove(row:any){try{await ElMessageBox.confirm('确定删除这条记录？','删除');const path=tab.value==='warehouses'?'/settings/warehouses/'+row.id+'/delete':tab.value==='addresses'?'/sta/addresses/'+row.id+'/delete':'/shipping/profiles/remove-record';await api(path,tab.value==='profiles'?{store:row.store,country:row.country,revision:row.revision}:{});await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
const settingsPager=useLocalPagination(()=>['warehouses','stores'].includes(tab.value)?filteredRows.value:rows.value)
</script>
<template><section class="panel settings"><el-radio-group v-model="tab"><el-radio-button v-if="can('settings.warehouses')" value="warehouses">仓库管理</el-radio-button><el-radio-button v-if="can('settings.stores')" value="stores">店铺授权管理</el-radio-button><el-radio-button v-if="can('settings.addresses')" value="addresses">地址管理</el-radio-button><el-radio-button v-if="can('settings.profiles')" value="profiles">合规信息</el-radio-button><el-radio-button v-if="can('settings.sync-data')" value="sync-data">同步数据</el-radio-button><el-radio-button v-if="session?.is_admin" value="ads-queue">广告消息队列</el-radio-button><el-radio-button v-if="can('settings.mail')" value="mail">绩效邮件</el-radio-button></el-radio-group><MailPanel v-if="tab==='mail'"/><DataSyncPanel v-else-if="tab==='sync-data'"/><AdsQueuePanel v-else-if="tab==='ads-queue'"/><CompliancePanel v-else-if="tab==='profiles'"/><template v-else><div class="settings-tools"><template v-if="['warehouses','stores'].includes(tab)"><el-input v-model="searchText" :placeholder="tab==='warehouses'?'搜索仓库名称':'搜索店铺名称'" clearable @clear="appliedSearch=searchText" @keyup.enter="appliedSearch=searchText"/><el-button type="primary" @click="appliedSearch=searchText">查询</el-button><el-button @click="searchText='';appliedSearch=''">重置</el-button></template><el-select v-if="tab==='addresses'" class="address-store-filter" v-model="store" placeholder="全部店铺" clearable filterable @change="load"><el-option value="" label="全部店铺"/><el-option v-for="s in stores" :value="s" :label="s"/></el-select><el-button @click="load">刷新</el-button><el-button v-if="can('settings.'+tab,'operate')&&(tab!=='stores'||session?.is_admin)" type="primary" @click="edit()">{{tab==='stores'?'新增店铺':tab==='warehouses'?'新增仓库':tab==='addresses'?'新增地址':'新增英代欧代'}}</el-button><TableReset table-key="SettingsPanel/table-1"/></div><el-alert v-if="error" :title="error" type="error"/><template v-if="true"><el-table :data="settingsPager.rows.value" border v-loading="busy" data-width-key="SettingsPanel/table-1" @header-dragend="(w:number,_:number,c:any)=>widths.resize('table-1',w,c)"><template v-if="tab==='warehouses'"><el-table-column column-key="c1" :width="widths.width('table-1','c1')" prop="name" label="仓库名称"/><el-table-column column-key="c2" :width="widths.width('table-1','c2')" prop="manager" label="负责人"/><el-table-column column-key="c3" :width="widths.width('table-1','c3')" prop="address" label="地址"/></template><template v-else-if="tab==='stores'"><el-table-column column-key="c4" :width="widths.width('table-1','c4')" prop="name" label="店铺"/><el-table-column column-key="c5" :width="widths.width('table-1','c5')" prop="seller_id" label="Seller ID"/><el-table-column column-key="c6" :width="widths.width('table-1','c6')" label="授权资料"><template #default="{row}">{{row.authorized?'已配置':'待补齐'}}</template></el-table-column><el-table-column label="广告授权"><template #default="{row}">{{row.ads_authorized?'已配置':'待补齐'}}</template></el-table-column><el-table-column column-key="c7" :width="widths.width('table-1','c7')" label="连接代理"><template #default="{row}">{{row.proxy_configured?'已配置':'未配置'}}</template></el-table-column></template><template v-else-if="tab==='addresses'"><el-table-column column-key="c8" :width="widths.width('table-1','c8')" prop="store" label="店铺"/><el-table-column column-key="c10" :width="widths.width('table-1','c10')" prop="label" label="地址名称"/><el-table-column column-key="address-type" label="类型" :width="widths.width('table-1','address-type',160)"><template #default="{row}">{{row.address_type==='1688'?'1688收货地址':'FBA发货地址'}}</template></el-table-column><el-table-column column-key="c11" :width="widths.width('table-1','c11')" prop="detail.name" label="联系人"/><el-table-column column-key="c12" :width="widths.width('table-1','c12',250)" prop="detail.addressLine1" label="街道地址" min-width="250"/></template><template v-else><el-table-column column-key="c13" :width="widths.width('table-1','c13')" prop="store" label="店铺"/><el-table-column column-key="c14" :width="widths.width('table-1','c14')" label="类型"><template #default="{row}">{{row.country==='UK'?'英代':'欧代'}}</template></el-table-column><el-table-column column-key="c15" :width="widths.width('table-1','c15')" prop="detail.representative_company" label="代理公司"/><el-table-column column-key="c16" :width="widths.width('table-1','c16')" prop="detail.manufacturer_company" label="制造商"/><el-table-column column-key="c17" :width="widths.width('table-1','c17')" label="资料检查"><template #default="{row}">{{row.missing?.length?'缺少：'+row.missing.join('、'):'完整'}}</template></el-table-column></template><el-table-column v-if="tab==='stores'" column-key="mail" label="授权邮箱" min-width="230"><template #default="{row}">{{row.mail?.email||'未连接'}}<div class="cell-sub">{{row.mail?.connected?'已授权':'未授权'}}</div></template></el-table-column><el-table-column column-key="c18" :width="widths.width('table-1','c18',tab==='stores'?230:210)" v-if="can('settings.'+tab,'operate')" label="操作" fixed="right" ><template #default="{row}"><el-button link type="primary" @click="edit(row)">{{tab==='stores'?'更新授权':'编辑'}}</el-button><el-button v-if="tab==='addresses'" link type="primary" @click="copyAddress(row)">复制</el-button><MailAuthorization v-if="tab==='stores'" :store="row.name" @changed="load"/><el-button v-if="tab!=='stores'" link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><AppPagination v-model:current-page="settingsPager.page.value" v-model:page-size="settingsPager.pageSize.value" :total="settingsPager.total.value"/></template>
<el-dialog class="settings-editor" top="4vh" v-model="dialog" :title="tab==='stores'?(editing?'更新店铺授权':'新增店铺'):editing?'编辑':'新增'" width="min(880px,95vw)"><el-form label-position="top" :disabled="busy"><template v-if="tab==='warehouses'"><el-form-item v-for="(label,key) in {name:'仓库名称',manager:'负责人',address:'地址'}" :label="label"><el-input v-model="form[key]"/></el-form-item></template><template v-else-if="tab==='stores'"><p>密钥和密码不回显；留空保留原值。更换授权后，新请求自动使用最新配置。</p><el-form-item label="店铺名称"><el-input v-model="form.name" :disabled="!!editing"/></el-form-item><h3>店铺 SP-API 授权</h3><div class="settings-grid"><el-form-item v-for="key in ['seller_id','client_id','client_secret','refresh_token']" :label="key"><el-input v-model="form[key]" :type="['client_secret','refresh_token'].includes(key)?'password':'text'" :placeholder="editing?.configured?.[key]?'已配置；留空保留':''" autocomplete="new-password"/></el-form-item></div><h3>连接代理</h3><div class="settings-grid"><el-form-item label="协议"><el-select v-model="form.proxy_protocol"><el-option v-for="v in ['http','https','socks5','socks5h']" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="IP / 主机"><el-input v-model="form.proxy_host" placeholder="留空表示不使用代理"/></el-form-item><el-form-item label="端口"><el-input-number v-model="form.proxy_port" :min="1" :max="65535"/></el-form-item><el-form-item label="账号"><el-input v-model="form.proxy_username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.proxy_password" type="password" autocomplete="new-password" :placeholder="editing?.configured?.proxy_password?'已配置；留空保留':''"/></el-form-item><el-form-item label="上游 HTTP 代理（选填，仅 SOCKS5 链路）"><el-input v-model="form.upstream_proxy" placeholder="http://主机:端口"/></el-form-item></div><h3>独立广告授权</h3><div class="settings-grid"><el-form-item v-for="key in ['ads_client_id','ads_client_secret','ads_refresh_token']" :label="key.replace('ads_','')"><el-input v-model="form[key]" :type="key==='ads_client_id'?'text':'password'" autocomplete="new-password" :placeholder="editing?.configured?.[key]?'已配置；留空保留':''"/></el-form-item><el-form-item label="api_url"><el-select v-model="form.ads_api_url"><el-option v-for="url in ['https://advertising-api-eu.amazon.com','https://advertising-api.amazon.com','https://advertising-api-fe.amazon.com']" :label="url" :value="url"/></el-select></el-form-item></div><el-form-item v-if="editing" label="清除已保存密钥（选填）"><el-checkbox-group v-model="form.clear_secrets"><el-checkbox v-for="k in ['client_secret','refresh_token','proxy_password','ads_client_secret','ads_refresh_token']" :value="k">{{k}}</el-checkbox></el-checkbox-group></el-form-item></template><template v-else><div class="settings-grid"><el-form-item label="店铺"><el-select v-model="form.store" :disabled="!!editing"><el-option v-for="s in stores" :value="s" :label="s"/></el-select></el-form-item><el-form-item v-if="tab!=='addresses'" label="代理类型"><el-select v-model="form.country" :disabled="!!editing&&tab==='profiles'"><el-option v-for="(n,k) in tab==='profiles'?{UK:'英代',EU:'欧代'}:{UK:'英国',DE:'德国',FR:'法国',ES:'西班牙',IT:'意大利',NL:'荷兰',BE:'比利时',PL:'波兰',SE:'瑞典',IE:'爱尔兰'}" :value="k" :label="n"/></el-select></el-form-item><template v-if="tab==='addresses'"><el-form-item label="类型"><el-select v-model="form.address_type" aria-label="地址类型"><el-option value="fba" label="FBA发货地址"/><el-option value="1688" label="1688收货地址"/></el-select></el-form-item><p class="address-scope">按店铺保存；做货件时仅带出 FBA发货地址。</p><el-form-item label="地址名称（选填）"><el-input v-model="form.label" placeholder="内部备注；留空按城市和街道自动命名" :maxlength="100"/></el-form-item><el-form-item v-for="(label,key) in addressFields" :label="label" :required="requiredAddressFields.includes(key)"><el-input v-model="form.detail[key]"/></el-form-item></template><template v-else><el-form-item v-for="(label,key) in profileFields" :label="label"><el-input v-model="form[key]" :type="key.includes('address')?'textarea':'text'"/></el-form-item><el-form-item label="到期日期"><el-date-picker v-model="form.representative_expires" value-format="YYYY-MM-DD"/></el-form-item><el-checkbox v-model="form.show_marks">打印14+、回收、CE、UKCA图标</el-checkbox></template></div></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></template></section></template>
<style scoped>.settings{padding:16px}.settings-tools{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin:16px 0}.settings-tools>.el-input{width:260px}.settings-tools>.address-store-filter{width:200px;flex:0 0 200px}.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.settings-grid .el-select{width:100%}.settings :deep(.settings-editor){max-height:92vh;display:flex;flex-direction:column}.settings :deep(.settings-editor .el-dialog__body){overflow:auto}.settings :deep(.settings-editor .el-dialog__footer){flex-shrink:0}@media(max-width:640px){.settings-grid{grid-template-columns:1fr}}</style>
